using System;\nusing NUnit.Framework;\nusing RestSharp;\nusing TechTalk.SpecFlow;\nusing AutomationFramework.API.BusinessLogic;\nusing Serilog;\n\nnamespace AutomationFramework.API.StepDefinitions\n{\n    [Binding]\n    public class PetstoreSteps\n    {\n        private readonly ScenarioContext _scenarioContext;\n        private readonly PetApiHelper _petApiHelper;\n        private RestResponse _response;\n\n        public PetstoreSteps(ScenarioContext scenarioContext)\n        {\n            _scenarioContext = scenarioContext;\n            _petApiHelper = new PetApiHelper();\n        }\n\n        [Given(\"the API endpoint is \\\"(.*)\\\"\")]\n        public void GivenTheApiEndpointIs(string endpoint)\n        {\n            _scenarioContext[\"Endpoint\"] = endpoint;\n            Log.Information(\"Endpoint set to: {Endpoint}\", endpoint);\n        }\n\n        [When(\"I send a POST request with the payload\")]\n        public void WhenISendAPostRequestWithThePayload()\n        {\n            var payload = new { id = 12345, name = \"Doggie\", status = \"available\" };\n            _response = _petApiHelper.SendPostRequest(_scenarioContext[\"Endpoint\"].ToString(), payload);\n            Log.Information(\"POST request sent with payload: {Payload}\", payload);\n        }\n\n        [When(\"I send a GET request for pet with ID \\\"(.*)\\\"\")]\n        public void WhenISendAGetRequestForPetWithId(string petId)\n        {\n            _response = _petApiHelper.SendGetRequest(_scenarioContext[\"Endpoint\"].ToString().Replace(\"{petId}\", petId));\n            Log.Information(\"GET request sent for pet ID: {PetId}\", petId);\n        }\n\n        [When(\"I send a PUT request with the updated payload\")]\n        public void WhenISendAPutRequestWithTheUpdatedPayload()\n        {\n            var payload = new { id = 12345, name = \"DoggieUpdated\", status = \"sold\" };\n            _response = _petApiHelper.SendPutRequest(_scenarioContext[\"Endpoint\"].ToString(), payload);\n            Log.Information(\"PUT request sent with updated payload: {Payload}\", payload);\n        }\n\n        [When(\"I send a DELETE request for pet with ID \\\"(.*)\\\"\")]\n        public void WhenISendADeleteRequestForPetWithId(string petId)\n        {\n            _response = _petApiHelper.SendDeleteRequest(_scenarioContext[\"Endpoint\"].ToString().Replace(\"{petId}\", petId));\n            Log.Information(\"DELETE request sent for pet ID: {PetId}\", petId);\n        }\n\n        [Then(\"I should receive a 200 OK response\")]\n        public void ThenIShouldReceiveA200OkResponse()\n        {\n            Assert.AreEqual(200, (int)_response.StatusCode, \"Expected 200 OK response, but got {Status